<div class="mb-4"><a href="/app/magazzino" class="text-decoration-none">← Torna al magazzino</a><h1 class="h2 mt-2"><?= $id?'Modifica prodotto':'Aggiungi prodotto' ?></h1><p class="text-secondary">La giacenza iniziale si registra come movimento di carico per mantenere uno storico corretto.</p></div><?php foreach($errors as $error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endforeach ?><form method="post" action="<?= $id?'/app/magazzino/'.(int)$id:'/app/magazzino' ?>" class="form"><?= $csrf->field() ?><div class="row g-3"><div class="col-md-8"><label class="form-label">Nome prodotto *<input class="form-control" name="nome" value="<?= e($prodotto['nome']) ?>" required></label></div><div class="col-md-4"><label class="form-label">Codice interno<input class="form-control" name="codice" value="<?= e($prodotto['codice']) ?>" placeholder="Facoltativo"></label></div><div class="col-md-4"><label class="form-label">Categoria<select class="form-select" name="categoria"><?php foreach(['prodotto'=>'Prodotto','esca'=>'Esca','materiale'=>'Materiale di consumo','attrezzatura'=>'Attrezzatura','altro'=>'Altro'] as $k=>$v): ?><option value="<?= e($k) ?>" <?= $prodotto['categoria']===$k?'selected':'' ?>><?= e($v) ?></option><?php endforeach ?></select></label></div><div class="col-md-4"><label class="form-label">Unità di misura<input class="form-control" name="unita_misura" value="<?= e($prodotto['unita_misura']?:'pz') ?>" placeholder="pz, kg, L"></label></div><div class="col-md-4"><label class="form-label">Produttore<input class="form-control" name="produttore" value="<?= e($prodotto['produttore']) ?>"></label></div><div class="col-md-6"><label class="form-label">Fornitore<input class="form-control" name="fornitore" value="<?= e($prodotto['fornitore']) ?>"></label></div><div class="col-md-3"><label class="form-label">Scorta minima<input class="form-control" type="number" min="0" step="0.001" name="scorta_minima" value="<?= e((string)$prodotto['scorta_minima']) ?>"></label></div><div class="col-md-3"><label class="form-label">Costo unitario (€)<input class="form-control" type="number" min="0" step="0.01" name="costo_acquisto" value="<?= e((string)$prodotto['costo_acquisto']) ?>"></label></div><div class="col-md-3"><label class="form-label">Prezzo di vendita (€)<input class="form-control" type="number" min="0" step="0.01" name="prezzo_vendita" value="<?= e((string)$prodotto['prezzo_vendita']) ?>"></label></div><div class="col-md-9"><label class="form-label">Descrizione<textarea class="form-control" name="descrizione" rows="2"><?= e($prodotto['descrizione']) ?></textarea></label></div><div class="col-12 form-check ms-2"><input class="form-check-input" type="checkbox" name="tracciamento_lotto" value="1" id="lotTracking" <?= !empty($prodotto['tracciamento_lotto'])?'checked':'' ?>><label class="form-check-label" for="lotTracking">Richiedi lotto e scadenza nei movimenti e negli interventi</label></div><div class="col-12"><label class="form-label">Note<textarea class="form-control" name="note" rows="2"><?= e($prodotto['note']) ?></textarea></label></div></div><div class="actions mt-4"><button class="btn btn-primary btn-lg">Salva prodotto</button><a class="btn btn-outline-secondary" href="<?= $id?'/app/magazzino/'.(int)$id:'/app/magazzino' ?>">Annulla</a></div></form>
